<script lang="ts">
	import { Check, Gauge, LoaderCircle, Save, SlidersHorizontal, Zap } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import { createConfigComponent, createInverter, getEdgeConfig, getEvnModbusStatus, getFelixPids, queryHistoricTimeseriesData, updateController, type RtsComponent } from '$lib/services/rts-api';
	let controlMode = $state<'LOCAL'|'EVN'>('LOCAL');
	let active = $state({ enabled:false, mode:'WATT' as 'WATT'|'PERCENT', limitWatt:0, limitPercent:0 });
	let reactive = $state({ enabled:false, mode:'VAR' as 'VAR'|'PERCENT', limitKvar:0, limitPercent:0 });
	let notice = $state('');
	let totalInverterPowerW = $state(0);
	let inverterIds = $state('');
	let activePid = $state('');
	let reactivePid = $state('');
	let saving = $state(false);
	let apiError = $state('');
	let edgeComponents=$state<Record<string,RtsComponent>>({});
	let historyPeriod=$state<'day'|'month'|'year'>('day');
	let historySource=$state<'meter'|'inverters'>('meter');
	let historyDate=$state(new Date().toISOString().slice(0,10));
	let historyMonth=$state(new Date().toISOString().slice(0,7));
	let historyYear=$state(new Date().getFullYear());
	let historyLoading=$state(false);let historyError=$state('');let historyResult=$state<any>(null);
	let evn = $state({pOutEnabled:null as boolean|null,pOutSetpointWatt:null as number|null,pOutSetpointPercent:null as number|null,qOutEnabled:null as boolean|null,qOutSetpointVar:null as number|null,qOutSetpointPercent:null as number|null});
	let locked = $derived(controlMode === 'EVN');
	const activeFactory='Controller.PvInverter.FixPowerLimit';
	const reactiveFactory='Controller.PvInverter.LimitReactivePower';
	const activeId='ctrlPvInverterFixPowerLimit0';
	const reactiveId='ctrlPvInverterLimitReactivePower0';

	onMount(()=>{void load();});
	async function load(){
		apiError='';
		try{
			const [edge,pids,status]=await Promise.all([getEdgeConfig(),getFelixPids(),getEvnModbusStatus()]); evn=status;edgeComponents=edge.components;
			const inverterEntries=Object.entries(edge.components).filter(([,component])=>String(component.factoryId??'').startsWith('PV-Inverter.')||String(component.factoryId??'').startsWith('PvInverter.')||String(component.factoryId??'').startsWith('pvinverter.'));
			inverterIds=inverterEntries.map(([id])=>id).join(','); totalInverterPowerW=inverterEntries.reduce((sum,[,component])=>sum+Number(component.properties?.maxActivePower??0),0);
			const a=Object.entries(edge.components).find(([,component])=>component.factoryId===activeFactory); const q=Object.entries(edge.components).find(([,component])=>component.factoryId===reactiveFactory);
			if(a){const [id,component]=a;const p=component.properties??{};activePid=pids.find((item)=>item.fpid===activeFactory&&item.nameHint?.includes(`[${String(p.alias??id)}]`))?.id??'';active.enabled=p.enabled===true||p.enabled==='true';active.limitWatt=Number(p.powerLimit??0)/1000;active.limitPercent=totalInverterPowerW?Math.round(Number(p.powerLimit??0)/totalInverterPowerW*10000)/100:0;}
			if(q){const [id,component]=q;const p=component.properties??{};reactivePid=pids.find((item)=>item.fpid===reactiveFactory&&item.nameHint?.includes(`[${String(p.alias??id)}]`))?.id??'';reactive.enabled=p.enabled===true||p.enabled==='true';reactive.mode=p.usePercent===true||p.usePercent==='true'?'PERCENT':'VAR';reactive.limitKvar=Number(p.reactivePowerLimit??0)/1000;reactive.limitPercent=Number(p.reactivePowerLimitPercent??0);}
			controlMode=((a?.[1].properties?.allowEvnControl===true)||(q?.[1].properties?.allowEvnControl===true))?'EVN':'LOCAL';
		}catch(error){apiError=error instanceof Error?error.message:'Could not load Hybrid Controller.';}
	}

	function activePayload(){
		const powerLimit=active.mode==='PERCENT'?Math.round((active.limitPercent/100)*totalInverterPowerW):Math.round(active.limitWatt*1000);
		return {apply:'true',factoryPid:'Controller.PvInverter.FixPowerLimit',alias:'ctrlPvInverterFixPowerLimit0',id:'ctrlPvInverterFixPowerLimit0',enabled:active.enabled,powerLimit,allowEvnControl:locked,'pvInverter.id':inverterIds,propertylist:'id,alias,enabled,powerLimit,allowEvnControl,pvInverter.id'};
	}
	function reactivePayload(){return {apply:'true',factoryPid:'Controller.PvInverter.LimitReactivePower',alias:'ctrlPvInverterLimitReactivePower0',id:'ctrlPvInverterLimitReactivePower0',enabled:reactive.enabled,usePercent:reactive.mode==='PERCENT',reactivePowerLimit:Math.round(reactive.limitKvar*1000),reactivePowerLimitPercent:reactive.limitPercent,allowEvnControl:locked,'pvInverter.id':inverterIds,propertylist:'id,alias,enabled,usePercent,reactivePowerLimit,reactivePowerLimitPercent,allowEvnControl,pvInverter.id'};}
	async function saveActive(){saving=true;apiError='';try{const payload=activePayload();if(activePid)await updateController(activePid,payload);else await createInverter(activeFactory,payload);notice='Active Power settings saved successfully.';await load();}catch(error){apiError=error instanceof Error?error.message:'Could not save Active Power settings.';}finally{saving=false;}}
	async function saveReactive(){saving=true;apiError='';try{const payload=reactivePayload();if(reactivePid)await updateController(reactivePid,payload);else await createInverter(reactiveFactory,payload);notice='Reactive Power settings saved successfully.';await load();}catch(error){apiError=error instanceof Error?error.message:'Could not save Reactive Power settings.';}finally{saving=false;}}
	async function saveMode(){saving=true;apiError='';try{const allow=controlMode==='EVN';const jobs:Promise<unknown>[]=[];if(activePid)jobs.push(createConfigComponent(activePid,{allowEvnControl:allow,enabled:true}));else if(allow)jobs.push(createConfigComponent(activeFactory,{id:activeId,alias:'Main PvInverter FixPowerLimit',enabled:true,allowEvnControl:true,usePercentage:false,powerLimit:0,powerLimitPercent:100}));if(reactivePid)jobs.push(createConfigComponent(reactivePid,{allowEvnControl:allow,enabled:true}));else if(allow)jobs.push(createConfigComponent(reactiveFactory,{id:reactiveId,alias:'Main PvInverter LimitReactivePower',enabled:true,allowEvnControl:true,usePercent:false,reactivePowerLimit:0,reactivePowerLimitPercent:100}));await Promise.all(jobs);notice=`Switched to ${allow?'EVN':'Local'} Control mode.`;await load();}catch(error){apiError=error instanceof Error?error.message:'Could not change control mode.';}finally{saving=false;}}
	function normalizeList(value:unknown){if(Array.isArray(value))return value.map(String).map((item)=>item.trim()).filter(Boolean);if(typeof value==='string')return value.split(',').map((item)=>item.trim()).filter(Boolean);return value==null?[]:[String(value)]}
	function historyChannels(){const inverterList=inverterIds.split(',').filter(Boolean);if(historyPeriod!=='day')return inverterList.map((id)=>`${id}/EnergyProductionToday`);if(historySource==='meter'){const meterPoi=edgeComponents.meterPOI?.properties??{};const ids=[...normalizeList(meterPoi.components??meterPoi['meter.id']??meterPoi.meterId),...normalizeList(edgeComponents.ctrlEvnModbus0?.properties?.['meter.id'])];return Array.from(new Set(ids)).map((id)=>`${id}/ActivePower`)}const channels=inverterList.map((id)=>`${id}/ActivePower`);for(const[id,component]of Object.entries(edgeComponents)){if(!/^SmartLogger\d+$/i.test(id))continue;for(const address of normalizeList(component.properties?.inverterAddresses)){const number=address.replace(/[^\d]/g,'');if(number)channels.push(`${id}/Pvinverter${number}/activepower`)}}return Array.from(new Set(channels))}
	function historyRange(){if(historyPeriod==='day')return{fromDate:historyDate,toDate:historyDate};if(historyPeriod==='month'){const[y,m]=historyMonth.split('-').map(Number);const last=new Date(y,m,0).getDate();return{fromDate:`${historyMonth}-01`,toDate:`${historyMonth}-${String(last).padStart(2,'0')}`}}return{fromDate:`${historyYear}-01-01`,toDate:`${historyYear}-12-31`}}
	async function loadHistory(){historyError='';const channels=historyChannels();if(!channels.length){historyError='No channel is available for the selected source.';historyResult=null;return}historyLoading=true;try{const range=historyRange();const response=await queryHistoricTimeseriesData(Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',range.fromDate,range.toDate,channels,historyPeriod==='day'?{value:5,unit:'MINUTES'}:{value:1,unit:'HOURS'});historyResult=(response as any)?.payload?.result??(response as any)?.result??response;}catch(error){historyError=error instanceof Error?error.message:'Could not load history.';}finally{historyLoading=false;}}
	let historySeries=$derived(Object.entries((historyResult?.data??{}) as Record<string,unknown[]>).map(([name,values])=>({name,values:values.map((value)=>value==null?0:Number(value)||0)})));
	function chartPoints(values:number[]){if(!values.length)return'';const max=Math.max(...values.map(Math.abs),1);return values.map((value,index)=>`${values.length===1?0:index/(values.length-1)*100},${48-(value/max)*43}`).join(' ')}
</script>

<section class="page"><div class="page-head"><div><h2>Hybrid Controller</h2><p>RTS power limitation and EVN control from the existing PPC module.</p></div></div>
	<div class="mode-bar"><div><span>Control mode</span><strong>{controlMode === 'LOCAL' ? 'Local Control' : 'EVN Control'}</strong></div><div class="mode-control"><div class="mode-buttons"><button class:active={controlMode==='LOCAL'} onclick={()=>controlMode='LOCAL'}>Local</button><button class:active={controlMode==='EVN'} onclick={()=>controlMode='EVN'}>EVN</button></div><button class="save-mode" onclick={saveMode} disabled={saving}>Apply mode</button></div></div>
	{#if apiError}<div class="error">{apiError}</div>{/if}
	{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}
	<div class="status-grid"><article><span><Zap size={18}/></span><div><small>Total inverter power</small><strong>{(totalInverterPowerW/1000).toFixed(2)} kW</strong></div></article><article><span><Gauge size={18}/></span><div><small>Active power setpoint</small><strong>{((evn.pOutSetpointWatt??0)/1000).toFixed(2)} kW / {evn.pOutSetpointPercent??0}%</strong></div></article><article><span><SlidersHorizontal size={18}/></span><div><small>Reactive power setpoint</small><strong>{((evn.qOutSetpointVar??0)/1000).toFixed(2)} kVAR / {evn.qOutSetpointPercent??0}%</strong></div></article></div>
	<section class="history"><header><div><h3>History</h3><p>Meter, inverter and Smart Logger channels from RTS historical timeseries.</p></div><div class="history-period"><button class:active={historyPeriod==='day'} onclick={()=>historyPeriod='day'}>Day</button><button class:active={historyPeriod==='month'} onclick={()=>{historyPeriod='month';historySource='inverters'}}>Month</button><button class:active={historyPeriod==='year'} onclick={()=>{historyPeriod='year';historySource='inverters'}}>Year</button></div></header><div class="history-tools"><div class="source"><button class:active={historySource==='meter'} disabled={historyPeriod!=='day'} onclick={()=>historySource='meter'}>Meter</button><button class:active={historySource==='inverters'} onclick={()=>historySource='inverters'}>Inverters</button></div>{#if historyPeriod==='day'}<input aria-label="History day" type="date" bind:value={historyDate}/>{:else if historyPeriod==='month'}<input aria-label="History month" type="month" bind:value={historyMonth}/>{:else}<input aria-label="History year" type="number" min="2000" max="2100" bind:value={historyYear}/>{/if}<button class="load-history" onclick={loadHistory} disabled={historyLoading}>{historyLoading?'Loading…':'View history'}</button></div>{#if historyError}<div class="history-error">{historyError}</div>{/if}{#if historySeries.length}<div class="legend">{#each historySeries as series,index}<span><i style={`--color:${['#2454b6','#24a165','#e4912e','#8756d8'][index%4]}`}></i>{series.name}</span>{/each}</div><div class="chart"><svg viewBox="0 0 100 50" preserveAspectRatio="none" role="img" aria-label="RTS history chart">{#each historySeries as series,index}<polyline points={chartPoints(series.values)} style={`stroke:${['#2454b6','#24a165','#e4912e','#8756d8'][index%4]}`}/>{/each}</svg></div>{:else if !historyLoading}<div class="history-empty">Select a source and time range to load historical data.</div>{/if}</section>
	<div class:locked class="control-grid"><section class="card"><header><div><h3>Active Power Limit Control</h3><p>Controller.PvInverter.FixPowerLimit</p></div><button class:enabled={active.enabled} class="switch" disabled={locked} onclick={()=>active.enabled=!active.enabled}><i></i>{active.enabled?'Enabled':'Disabled'}</button></header>{#if locked}<div class="lock">Locked in EVN Mode</div>{/if}<div class="body"><div class="modes"><button class:active={active.mode==='WATT'} disabled={!active.enabled||locked} onclick={()=>active.mode='WATT'}>Limit by kW</button><button class:active={active.mode==='PERCENT'} disabled={!active.enabled||locked} onclick={()=>active.mode='PERCENT'}>Limit by Percent (%)</button></div><label>Limit Value (kW)<input type="number" min="0" disabled={!active.enabled||locked||active.mode!=='WATT'} bind:value={active.limitWatt}/><small>Total available: {(totalInverterPowerW/1000).toFixed(2)} kW</small></label><label>Limit Value (%)<input type="number" min="0" max="100" disabled={!active.enabled||locked||active.mode!=='PERCENT'} bind:value={active.limitPercent}/><small>Total available power: 100%</small></label></div><footer><button class="primary" disabled={locked||saving} onclick={saveActive}>{#if saving}<LoaderCircle size={16}/>{:else}<Save size={16}/>{/if}Save</button></footer></section>
	<section class="card"><header><div><h3>Reactive Power Control</h3><p>Controller.PvInverter.LimitReactivePower</p></div><button class:enabled={reactive.enabled} class="switch" disabled={locked} onclick={()=>reactive.enabled=!reactive.enabled}><i></i>{reactive.enabled?'Enabled':'Disabled'}</button></header>{#if locked}<div class="lock">Locked in EVN Mode</div>{/if}<div class="body"><div class="modes"><button class:active={reactive.mode==='VAR'} disabled={!reactive.enabled||locked} onclick={()=>reactive.mode='VAR'}>Limit by kVAR</button><button class:active={reactive.mode==='PERCENT'} disabled={!reactive.enabled||locked} onclick={()=>reactive.mode='PERCENT'}>Limit by Percent (%)</button></div><label>Limit Value (kVAR)<input type="number" min="0" disabled={!reactive.enabled||locked||reactive.mode!=='VAR'} bind:value={reactive.limitKvar}/></label><label>Limit Value (%)<input type="number" min="0" max="100" disabled={!reactive.enabled||locked||reactive.mode!=='PERCENT'} bind:value={reactive.limitPercent}/><small>Reactive power limit as percentage 0–100</small></label></div><footer><button class="primary" disabled={locked||saving} onclick={saveReactive}>{#if saving}<LoaderCircle size={16}/>{:else}<Save size={16}/>{/if}Save</button></footer></section></div>
</section>

<style>
	.page{animation:enter .18s ease-out}.page-head{margin-bottom:18px}.page-head h2{margin:0;color:#172b4d;font-size:24px;font-weight:500}.page-head p{margin:7px 0 0;color:#718096;font-size:16px}.mode-bar{display:flex;align-items:center;justify-content:space-between;padding:14px 17px;border:1px solid #dde5f0;border-radius:11px;background:#fff}.mode-bar span,.mode-bar strong{display:block}.mode-bar span{color:#8792a4;font-size:12px}.mode-bar strong{margin-top:4px;color:#31415c;font-size:15px;font-weight:500}.mode-control{display:flex;gap:8px}.mode-buttons{display:flex;padding:3px;border-radius:8px;background:#edf1f7}.mode-buttons button{height:33px;padding:0 14px;border:0;border-radius:6px;color:#68768c;background:transparent;cursor:pointer;font:inherit}.mode-buttons button.active{color:#1749ad;background:#fff;box-shadow:0 1px 4px rgba(31,50,80,.1)}.save-mode{padding:0 12px;border:0;border-radius:7px;color:#fff;background:#1749ad;font:inherit;cursor:pointer}.notice,.error{display:flex;align-items:center;gap:7px;margin:13px 0 0;padding:10px 12px;border-radius:8px;font-size:13px}.notice{border:1px solid #cae7d5;color:#28784e;background:#f2fbf5}.error{border:1px solid #f0ccc8;color:#b42318;background:#fff2f1}.status-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:15px 0}.status-grid article{display:flex;align-items:center;gap:11px;padding:14px;border:1px solid #e1e7f0;border-radius:10px;background:#fff}.status-grid article>span{display:grid;place-items:center;width:34px;height:34px;border-radius:9px;color:#2754b5;background:#eaf0ff}.status-grid small,.status-grid strong{display:block}.status-grid small{color:#8792a4}.status-grid strong{margin-top:4px;color:#30415c;font-size:15px;font-weight:500}.control-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.card{position:relative;overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.card header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 18px;border-bottom:1px solid #edf0f4}.card h3{margin:0;color:#30415c;font-size:16px;font-weight:500}.card header p{margin:4px 0 0;color:#8792a4;font-size:12px}.switch{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 9px;border:1px solid #d7dfeb;border-radius:16px;color:#77849a;background:#fff;cursor:pointer;font:inherit;font-size:12px}.switch i{width:8px;height:8px;border-radius:50%;background:#9ba6b5}.switch.enabled{border-color:#b9dfc9;color:#24764d;background:#f1fbf5}.switch.enabled i{background:#2eae68}.body{display:grid;gap:14px;padding:18px}.modes{display:flex;gap:6px}.modes button{flex:1;min-height:36px;border:1px solid #d9e1ed;border-radius:7px;color:#627188;background:#fff;cursor:pointer;font:inherit;font-size:13px}.modes button.active{border-color:#aac0ee;color:#1749ad;background:#edf3ff}.body label{display:grid;gap:6px;color:#536078;font-size:13px}.body input{height:39px;padding:0 11px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit}.body input:disabled,.modes button:disabled{opacity:.55;cursor:not-allowed}.body small{color:#8a95a7}.card footer{display:flex;justify-content:flex-end;padding:12px 18px;border-top:1px solid #edf0f4}.primary{display:inline-flex;align-items:center;gap:7px;min-height:37px;padding:0 14px;border:0;border-radius:7px;color:#fff;background:#1749ad;cursor:pointer;font:inherit}.primary:disabled{opacity:.45;cursor:not-allowed}.lock{position:absolute;z-index:2;top:66px;right:18px;padding:5px 8px;border-radius:12px;color:#8b5c1b;background:#fff5dd;font-size:11px}@keyframes enter{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}@media(max-width:950px){.control-grid{grid-template-columns:1fr}}@media(max-width:680px){.status-grid{grid-template-columns:1fr}.mode-bar{align-items:flex-start;flex-direction:column;gap:12px}.mode-control,.mode-buttons{width:100%}.mode-buttons button{flex:1}.modes{flex-direction:column}}
	.history{margin:0 0 15px;overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.history>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;border-bottom:1px solid #edf0f4}.history h3{margin:0;color:#30415c;font-size:16px;font-weight:500}.history header p{margin:4px 0 0;color:#8792a4;font-size:12px}.history-period,.source{display:flex;padding:3px;border-radius:8px;background:#edf1f7}.history-period button,.source button{height:31px;padding:0 12px;border:0;border-radius:6px;color:#68768c;background:transparent;font:inherit;cursor:pointer}.history-period button.active,.source button.active{color:#1749ad;background:#fff;box-shadow:0 1px 4px rgba(31,50,80,.1)}.history-tools{display:flex;align-items:center;gap:9px;padding:12px 17px}.history-tools input{height:37px;padding:0 10px;border:1px solid #d7dfeb;border-radius:7px;color:#35445e;background:#fff;font:inherit}.load-history{height:37px;margin-left:auto;padding:0 12px;border:0;border-radius:7px;color:#fff;background:#1749ad;font:inherit;cursor:pointer}.history-error{margin:0 17px 12px;padding:9px 11px;border-radius:7px;color:#b42318;background:#fff1f0;font-size:12px}.history-empty{display:grid;min-height:120px;place-items:center;border-top:1px solid #edf0f4;color:#8792a4;font-size:13px}.legend{display:flex;flex-wrap:wrap;gap:11px;padding:0 17px 9px;color:#65738a;font-size:11px}.legend span{display:flex;align-items:center;gap:5px}.legend i{width:8px;height:8px;border-radius:50%;background:var(--color)}.chart{height:150px;padding:5px 17px 14px}.chart svg{width:100%;height:100%;overflow:visible;border-left:1px solid #e9edf3;border-bottom:1px solid #e9edf3;background:repeating-linear-gradient(to bottom,transparent 0,transparent 31px,#eef2f7 32px)}.chart polyline{fill:none;stroke-width:1.2;vector-effect:non-scaling-stroke}@media(max-width:680px){.history>header,.history-tools{align-items:stretch;flex-direction:column}.history-period,.source{width:100%}.history-period button,.source button{flex:1}.load-history{width:100%;margin-left:0}}
</style>
